{{(() => {
    const d = GetOrderDetails.data?.[0];
    if (!d) return '';
    const en = appsmith.store.bo_lang === 'en';
    const at = (x) => x ? moment(x).format('DD.MM.YYYY HH:mm') : '-';
    if (d.delivered_at) return (en ? 'Delivered on ' : 'Доставена на ') + at(d.delivered_at);
    if (d.returned_at) return (en ? 'Returned on ' : 'Върната на ') + at(d.returned_at);
    if (d.cancelled_at) return (en ? 'Cancelled on ' : 'Отказана на ') + at(d.cancelled_at);
    if (d.started_at) return (en ? 'On its way since ' : 'В път от ') + at(d.started_at);
    if (d.dispatched_at) return (en ? 'Dispatched on ' : 'Възложена на ') + at(d.dispatched_at);
    return (en ? 'Created on ' : 'Създадена на ') + at(d.created_at);
  })()}}
